# R golden fixtures for gaply_core's Wilcoxon signed-rank and Friedman tests as
# an analysis (Research OS, Phase 8Z-1, decisions 636 and 638, capability
# stats.analyze.related_ranks).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_related_ranks_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into
# Gaply. Base R only: the stats package (rank, median, wilcox.test,
# friedman.test, pnorm, pchisq). Written with R 4.6.1, whose version the
# files' headers record.
#
# Writes, next to this script:
#   * data_*.csv: one synthetic dataset per case (a two-line '#' header, then
#     `id,` and the columns), each number %.17g of R's own double, so the file
#     names that double exactly; every number below comes from R's in-memory
#     doubles, never from text R parsed back, since R's parser is not exact at
#     17 digits on this platform;
#   * counts_*.csv: for the cases of 100,000 rows, a list of the columns' values
#     and n, which the test expands: each line in the file's order repeated n
#     times;
#   * cases.tsv: each case's file, its columns' headers in the list's order and
#     its missing codes;
#   * expected.tsv: R's answer for every case, one number per row (case, key,
#     value), the value as %.17g; "nc <code>" for a number Gaply gives as not
#     computable; "absent" where Gaply gives none; for a refusal, the code and
#     its parameters.
#
# A row is used only when every chosen column has a number that is not a ticked
# code; a row left out is counted once, under the first column in the list's
# order without one.
#
# Where each number comes from:
#   * two columns, the Wilcoxon signed-rank test, d = first - second:
#     wilcox.test(first, second, paired = TRUE, exact = FALSE, correct = FALSE)
#     for V and the asymptotic p, which drops zero differences; R's exact test
#     since 4.6.0 keeps zeros and handles ties, so exact = TRUE is asked for only
#     on cases with no tied |d| and no zero. z, T minus, the rank-biserial
#     correlation, each side's counts, rank sums and means: no base function
#     gives them, so THE SAME FORMULAS ARE WRITTEN TWICE, here and in gaply_core;
#   * three or more columns, the Friedman test: friedman.test on the complete
#     rows' matrix, its statistic as q_friedman_test, its df and p. Gaply's Q is
#     (12 / (n k (k + 1))) sum D_j^2 / C, D_j = R_j - n (k + 1) / 2, written
#     twice, and written as q; Kendall's W, Q / (n (k - 1)), written twice too.
#   * tie runs from rle(sort(...)), not table(), since table() rounds doubles to
#     15 digits; medians from median(), and where a median is not finite the
#     case's value is "nc stats.related_ranks.overflow".
#
# Synthetic data only. No manuscript or data of anyone's is read.

here <- local({
  a <- commandArgs(trailingOnly = FALSE)
  f <- sub("^--file=", "", a[grep("^--file=", a)])
  if (length(f)) dirname(normalizePath(f)) else getwd()
})
setwd(here)

HEADER <- c(
  "# Synthetic data for gaply_core's related rank tests R golden fixtures (Research OS, Phase 8Z-1).",
  "# Generated by /usr/local/bin/Rscript make_related_ranks_fixtures.R (do not edit by hand)."
)
fmt <- function(x) if (is.character(x)) x else if (is.na(x)) "NA" else sprintf("%.17g", x)
f17 <- function(x) ifelse(is.na(x), "", sprintf("%.17g", x))

cases <- character()
expected <- character()
emit <- function(case, key, value) {
  expected <<- c(expected, paste(case, key, fmt(value), sep = "\t"))
}
add_case <- function(case, file, columns, codes) {
  cases <<- c(cases, paste(case, file, paste(columns, collapse = " "),
                           if (length(codes)) paste(vapply(codes, fmt, ""), collapse = " ") else "-", sep = "\t"))
}
NC <- function(code) paste0("nc stats.related_ranks.", code)

# A data file of numeric columns, NA written empty; text columns pass as written.
write_data <- function(name, m, order_rows = TRUE) {
  n <- nrow(m)
  o <- if (order_rows) order((seq_len(n) * 7919) %% 10007, seq_len(n)) else seq_len(n)
  m <- m[o, , drop = FALSE]
  cols <- lapply(seq_len(ncol(m)), function(j) if (is.character(m[, j])) m[, j] else f17(m[, j]))
  path <- paste0("data_", name, ".csv")
  writeLines(c(HEADER, paste(c("id", colnames(m)), collapse = ","),
               do.call(paste, c(list(seq_len(n)), cols, sep = ","))), path, useBytes = TRUE)
  m
}

# Each row of values repeated n times, in the file's order.
write_counts <- function(name, values, n) {
  path <- paste0("counts_", name, ".csv")
  cols <- lapply(seq_len(ncol(values)), function(j) f17(values[, j]))
  writeLines(c(HEADER, paste(c(colnames(values), "n"), collapse = ","),
               do.call(paste, c(cols, list(n), sep = ","))), path, useBytes = TRUE)
  values[rep(seq_len(nrow(values)), n), , drop = FALSE]
}

# The analysis of matrix `m` of the chosen columns, in the list's order.
analyse <- function(case, m, codes = numeric()) {
  k <- ncol(m)
  n_rows <- nrow(m)
  value <- !is.na(m)
  coded <- value & (m %in% codes)
  dim(coded) <- dim(m)
  good <- value & !coded
  used <- rowSums(good) == k
  counts_missing <- numeric(k); counts_code <- numeric(k)
  for (r in which(!used)) {
    j <- which(!good[r, ])[1]
    if (value[r, j]) counts_code[j] <- counts_code[j] + 1 else counts_missing[j] <- counts_missing[j] + 1
  }
  for (j in seq_len(k)) {
    emit(case, sprintf("excluded.%d.missing_value", j - 1), counts_missing[j])
    emit(case, sprintf("excluded.%d.missing_code", j - 1), counts_code[j])
  }
  x <- m[used, , drop = FALSE]
  rows <- as.numeric(nrow(x))
  emit(case, "rows_used", rows); emit(case, "columns", k)
  for (j in seq_len(k)) emit(case, sprintf("column.%d.median", j - 1), median(x[, j]))
  if (k == 2) wilcoxon(case, x, rows) else friedman(case, x, rows, k)
}

wilcoxon <- function(case, x, rows) {
  d0 <- x[, 1] - x[, 2]
  zeros <- sum(d0 == 0)
  d <- d0[d0 != 0]
  n <- as.numeric(length(d))
  emit(case, "wilcoxon.n", n); emit(case, "wilcoxon.zero_differences", zeros)
  m <- median(d0)
  emit(case, "wilcoxon.median_difference", if (is.finite(m)) m else NC("overflow"))
  r <- rank(abs(d), ties.method = "average")
  tt <- as.numeric(rle(sort(abs(d)))$lengths)
  TS <- sum(tt^3 - tt)
  emit(case, "wilcoxon.tie_runs", sum(tt >= 2))
  neg <- r[d < 0]; pos <- r[d > 0]
  emit(case, "wilcoxon.negative.count", length(neg)); emit(case, "wilcoxon.positive.count", length(pos))
  emit(case, "wilcoxon.negative.rank_sum", sum(neg)); emit(case, "wilcoxon.positive.rank_sum", sum(pos))
  emit(case, "wilcoxon.negative.mean_rank", if (length(neg)) sum(neg) / length(neg) else "absent")
  emit(case, "wilcoxon.positive.mean_rank", if (length(pos)) sum(pos) / length(pos) else "absent")
  ties <- length(tt) < n
  has_zero <- zeros > 0
  big <- n >= 50
  if (n == 0) {
    emit(case, "wilcoxon.v", 0); emit(case, "wilcoxon.t_minus", 0)
    for (key in c("z", "p", "rank_biserial")) emit(case, paste0("wilcoxon.", key), NC("all_differences_zero"))
    emit(case, "wilcoxon.exact_p", "absent")
  } else {
    w <- suppressWarnings(wilcox.test(x[, 1], x[, 2], paired = TRUE, exact = FALSE, correct = FALSE))
    V <- unname(w$statistic)
    stopifnot(V == sum(pos))
    top <- n * (n + 1) / 2
    sigma <- sqrt(n * (n + 1) * (2 * n + 1) / 24 - TS / 48)
    z <- (V - n * (n + 1) / 4) / sigma
    stopifnot(abs(2 * pnorm(-abs(z)) - w$p.value) <= 1e-9 * w$p.value)
    emit(case, "wilcoxon.v", V); emit(case, "wilcoxon.t_minus", top - V)
    emit(case, "wilcoxon.z", z); emit(case, "wilcoxon.p", w$p.value)
    emit(case, "wilcoxon.rank_biserial", (V - (top - V)) / top)
    if (!ties && !has_zero && !big) {
      emit(case, "wilcoxon.exact_p", wilcox.test(x[, 1], x[, 2], paired = TRUE, exact = TRUE)$p.value)
    } else {
      emit(case, "wilcoxon.exact_p", "absent")
    }
  }
  emit(case, "note.exact_not_given_ties", as.numeric(ties))
  emit(case, "note.exact_not_given_zeros", as.numeric(has_zero))
  emit(case, "note.exact_not_given_size", as.numeric(big))
  emit(case, "note.zero_differences_dropped", as.numeric(has_zero))
  emit(case, "note.rows_below_five", as.numeric(n < 5))
}

friedman <- function(case, x, rows, k) {
  r <- t(apply(x, 1, rank, ties.method = "average"))
  rs <- colSums(r)
  TS <- 0; all_tied <- TRUE
  for (i in seq_len(nrow(x))) {
    tt <- rle(sort(x[i, ]))$lengths
    TS <- TS + sum(tt^3 - tt)
    if (length(tt) != 1) all_tied <- FALSE
  }
  emit(case, "friedman.df", k - 1)
  for (j in seq_len(k)) {
    emit(case, sprintf("friedman.column.%d.rank_sum", j - 1), rs[j])
    emit(case, sprintf("friedman.column.%d.mean_rank", j - 1), rs[j] / rows)
  }
  if (all_tied) {
    for (key in c("q", "p", "kendalls_w")) emit(case, paste0("friedman.", key), NC("all_values_tied"))
  } else {
    D <- rs - rows * (k + 1) / 2
    C <- 1 - TS / (rows * (k^3 - k))
    Q <- (12 / (rows * k * (k + 1))) * sum(D^2) / C
    ft <- friedman.test(x)
    stopifnot(unname(ft$parameter) == k - 1)
    emit(case, "friedman.q", Q)
    emit(case, "friedman.q_friedman_test", unname(ft$statistic))
    emit(case, "friedman.p", ft$p.value)
    emit(case, "friedman.kendalls_w", Q / (rows * (k - 1)))
  }
  emit(case, "note.exact_not_given_ties", 0)
  emit(case, "note.exact_not_given_zeros", 0)
  emit(case, "note.exact_not_given_size", 0)
  emit(case, "note.zero_differences_dropped", 0)
  emit(case, "note.rows_below_five", as.numeric(rows < 5))
}

refuse <- function(case, code, params = list()) {
  emit(case, "refused", paste0("stats.related_ranks.", code))
  for (p in names(params)) emit(case, paste0("refused.", p), params[[p]])
}

run <- function(case, m, codes = numeric()) {
  m2 <- write_data(case, m)
  add_case(case, paste0("data_", case, ".csv"), colnames(m), codes)
  analyse(case, m2, codes)
}
mat <- function(...) {
  a <- list(...)
  m <- do.call(cbind, a)
  colnames(m) <- names(a)
  m
}

set.seed(80638)
distinct <- function(n, step = 0.137) step * sample.int(n * 3, n)

# ---- two columns ---------------------------------------------------------
run("w_small", mat(a = c(1.25, 3.5, 2.75, 5.9, 4.15, 7.3, 6.05, 8.4), b = c(2.5, 3.1, 4.25, 1.6, 5.05, 4.2, 3.95, 2.3)))
run("w_tied_abs", mat(a = c(4, 7, 3, 9, 6, 2, 8, 5), b = c(2, 5, 1, 11, 8, 4, 10, 7)))
run("w_zeros", mat(a = c(4, 7, 3, 9, 6, 2.5, 8, 5.5), b = c(4, 5, 3, 11, 8, 4.25, 8, 9)))
run("w_all_zero", mat(a = c(1, 2, 3, 4), b = c(1, 2, 3, 4)))
d <- distinct(49, 0.25); base <- 100 + 0.5 * seq_len(49)
run("w_49", mat(a = base + d * ifelse(seq_len(49) %% 3 == 0, -1, 1), b = base))
d <- distinct(50, 0.25); base <- 100 + 0.5 * seq_len(50)
run("w_50", mat(a = base + d * ifelse(seq_len(50) %% 3 == 0, -1, 1), b = base))
run("w_one_pair", mat(a = 3, b = 1.5))
run("w_small_reversed", mat(b = c(2.5, 3.1, 4.25, 1.6, 5.05, 4.2, 3.95, 2.3), a = c(1.25, 3.5, 2.75, 5.9, 4.15, 7.3, 6.05, 8.4)))
run("w_one_sign", mat(a = c(5, 6, 7.5, 8, 9.25, 10), b = c(4, 4.5, 3, 7, 2, 1)))
# 1.5 * 2^1023 and its negative: finite, and their differences overflow.
big <- 1.5 * 2^1023
run("w_overflow", mat(a = c(big, 1, 2, 3, 10), b = c(-big, 5, 7.5, 12.25, 2)))
run("w_overflow_both_signs", mat(a = c(big, -big, 1, 2, 3, 10), b = c(-big, big, 5, 7.5, 12.25, 2)))

# 100,000 rows: tied |d| and zero differences among them.
yv <- 1:60
a <- rep(yv, each = 5)
b <- a + rep(c(-2, -1, 0, 1, 3), 60)
cnt <- 300 + (a * 37 + b * 11) %% 80
scale <- 100000 / sum(cnt); cnt <- floor(cnt * scale); cnt[1] <- cnt[1] + 100000 - sum(cnt)
values <- cbind(a = a, b = b)
m <- write_counts("w_large", values, cnt)
add_case("w_large", "counts_w_large.csv", c("a", "b"), numeric()); analyse("w_large", m)

# ---- three or more columns -----------------------------------------------
run("f_small", mat(p = c(1.25, 3.5, 2.75, 5.9, 4.15, 7.3), q = c(2.5, 3.1, 4.25, 1.6, 5.05, 4.2), r = c(3.75, 0.9, 6.5, 2.2, 8.1, 3.6)))
run("f_ties", mat(p = c(1, 2, 3, 4, 2, 5, 1), q = c(1, 3, 3, 2, 4, 5, 2), r = c(2, 3, 1, 4, 4, 5, 2)))
run("f_all_tied", mat(p = c(1, 2, 3, 4), q = c(1, 2, 3, 4), r = c(1, 2, 3, 4)))
set.seed(80639)
m50 <- sapply(1:50, function(j) round(runif(30, 0, 100), 2) + j * 0.3)
colnames(m50) <- sprintf("c%02d", 1:50)
run("f_50_columns", m50)
yv <- 1:40
a <- rep(yv, each = 6)
b <- a + rep(c(-1, 0, 1, 2, -2, 0), 40)
c <- a + rep(c(1, -1, 0, -3, 2, 0), 40)
cnt <- 300 + (a * 13 + b * 7 + c * 3) %% 90
cnt <- floor(cnt * 100000 / sum(cnt)); cnt[1] <- cnt[1] + 100000 - sum(cnt)
values <- cbind(a = a, b = b, c = c)
m <- write_counts("f_large", values, cnt)
add_case("f_large", "counts_f_large.csv", c("a", "b", "c"), numeric()); analyse("f_large", m)

# ---- missing values and codes, listwise, each row once under the first ----
m <- mat(a = c(1.5, NA, 3.5, -9, 5.5, 6.5, NA, 8.5, 9.5, 10.5),
         b = c(2.25, 3.25, NA, 4.75, -9, 7.25, -9, 1.25, 0.75, 12.25),
         c = c(4.5, 1.5, 2.5, NA, 3.25, -9, NA, 6.75, 2.75, 5.25))
run("missing_three", m, c(-9))
run("missing_three_order", m[, c("c", "a", "b")], c(-9))
run("missing_two", m[, c("b", "a")], c(-9, 99))

# ---- refusals, one for each check ---------------------------------------
base <- mat(a = c(1.5, 2.5, 3.5, 4.5, 5.5), b = c(2.75, 1.25, 4.25, 3.75, 6.25), c = c(9, 8, 7, 6, 5.5))
write_data("refuse_base", base)
add_case("refuse_code_not_finite", "data_refuse_base.csv", c("a", "b"), "NaN")
refuse("refuse_code_not_finite", "missing_code_not_finite", list(index = 0))
add_case("refuse_too_few_columns", "data_refuse_base.csv", c("a"), numeric())
refuse("refuse_too_few_columns", "too_few_columns", list(count = 1))
m51 <- sapply(1:51, function(j) c(1, 2, 3) + j / 10)
colnames(m51) <- sprintf("c%02d", 1:51)
write_data("refuse_51_columns", m51)
add_case("refuse_too_many_columns", "data_refuse_51_columns.csv", colnames(m51), numeric())
refuse("refuse_too_many_columns", "too_many_columns", list(count = 51, limit = 50))
add_case("refuse_column_repeated", "data_refuse_base.csv", c("a", "b", "a"), numeric())
refuse("refuse_column_repeated", "column_repeated", list(column = "a"))
add_case("refuse_unknown_column", "data_refuse_base.csv", c("a", "nosuch"), numeric())
refuse("refuse_unknown_column", "unknown_column", list())
text_m <- cbind(a = c("1", "2", "x", "4", "words"), b = c("2", "3", "4", "5", "6"))
write_data("refuse_text", text_m)
add_case("refuse_column_holds_text", "data_refuse_text.csv", c("a", "b"), numeric())
refuse("refuse_column_holds_text", "column_holds_text", list(column = "a", count = 2))
inf_m <- cbind(a = c("1", "Inf", "3", "4", "x"), b = c("2", "3", "4", "5", "6"))
write_data("refuse_infinite", inf_m)
add_case("refuse_column_non_finite", "data_refuse_infinite.csv", c("a", "b"), numeric())
refuse("refuse_column_non_finite", "column_non_finite", list(column = "a", count = 1))
holes <- mat(a = c(1, NA, 3), b = c(NA, 2, NA))
write_data("refuse_no_rows", holes)
add_case("refuse_no_complete_rows", "data_refuse_no_rows.csv", c("a", "b"), numeric())
refuse("refuse_no_complete_rows", "no_complete_rows", list())

stamp <- c("# written by: /usr/local/bin/Rscript make_related_ranks_fixtures.R",
           sprintf("# %s, base R stats only", R.version.string))
writeLines(c(stamp, "case\tfile\tcolumns\tmissing_codes", cases), "cases.tsv", useBytes = TRUE)
writeLines(c(stamp, "case\tkey\tvalue", expected), "expected.tsv", useBytes = TRUE)
cat(sprintf("%d cases, %d expected values\n", length(cases), length(expected)))
